def shortest_path(graph, source, target, max_steps=1000, step=0):
    import heapq

    def dijkstra(graph, source):
        queue = [(0, source)]  # (distance, node)
        visited = set()
        path = {}

        while queue:
            (distance, current) = heapq.heappop(queue)
            if current in visited:
                continue
            visited.add(current)

            if current == target:
                return (distance, path)

            for neighbor, weight in graph.get(current, []):
                if neighbor not in visited:
                    new_distance = distance + weight
                    if neighbor not in path or new_distance < path[neighbor]:
                        path[neighbor] = new_distance
                        heapq.heappush(queue, (new_distance, neighbor))

            # Limiting the depth of the search
            if step >= max_steps:
                return (float("inf"), None)
            step += 1

        return (float("inf"), None)

    if source == target:
        return (0, [source])

    distance, path = dijkstra(graph, source)

    if distance != float("inf"):
        return (distance, path)
    else:
        return (float("inf"), None)

