def shortest_path(graph, source, target):
    # Edge case: if the source is the same as target, the path is trivial
    if source == target:
        return (0, [source])

    # Initialize the distance dictionary with infinity for all nodes except the source
    distance = {node: float('inf') for node in graph}
    distance[source] = 0

    # Initialize the priority queue (heap) with the starting node, including the distance to itself
    priority_queue = [(0, source)]

    # Perform the Dijkstra's algorithm
    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we reached the target, we can stop the algorithm
        if current_node == target:
            return (current_distance, [target])

        # Skip if the current distance is not minimal
        if current_distance > distance[current_node]:
            continue

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance_neighbor = current_distance + weight
            if distance_neighbor < distance[neighbor]:
                # If the current distance is better, update the distance and push to the priority queue
                distance[neighbor] = distance_neighbor
                heapq.heappush(priority_queue, (distance_neighbor, neighbor))

    # If no path to the target is found
    return (float('inf'), None)

