import heapq

def shortest_path(graph, source, target):
    # Priority queue to hold (distance, node, path)
    pq = [(0, source, [])]
    # Dictionary to hold the shortest distance to each node
    distances = {node: float('inf') for node in graph}
    # Dictionary to hold the shortest path to each node
    previous = {node: None for node in graph}
    distances[source] = 0

    while pq:
        # Pop the node with the smallest distance
        current_distance, current_node, current_path = heapq.heappop(pq)
        if current_node == target:
            # When we find the target node, reconstruct the path
            path = [current_node] + current_path
            return (current_distance, path)
        if current_node != target and current_distance > distances[current_node]:
            continue  # Skip this path, it's not optimal
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor, current_path + [current_node]))

    # If we reach this point, there is no path between source and target
    return (float("inf"), None)

