```python
from collections import deque

def shortest_path(graph, source, target):
    # If the source is the target, the path is just the source.
    if source == target:
        return (0, [source])

    # Initialize BFS queue with source node, and a dictionary to store the shortest path and distance.
    queue = deque([(source, [source])])
    visited = {source}

    # Run BFS
    while queue:
        current_node, path = queue.popleft()
        if current_node == target:
            return (len(path) - 1, path)

        for neighbor, weight in graph.get(current_node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + [neighbor]))

    # If the target is not reachable, return infinity and None.
    return (float("inf"), None)

# Example usage:
