    'B': [('C', 1), ('D', 4)],
    'C': [('D', 1)],
    'D': [('C', 1)]
}

source = 'A'
target = 'D'
print(shortest_path(graph, source, target))  # Expected output: (3, ['A', 'B', 'D'])
