def shortest_path(graph, start, **max_steps):
    return _shortest_path(graph, **max_steps)

def _shortest_path(graph, source, target=None, max_steps=float("inf"), visited=None, edge_weights=None, path=None):
    if visited is None:
        visited = set()
    if path is None:
        path = [source]
    if edge_weights is None:
        edge_weights = {}
        for node in graph:
            edge_weights[node] = [1 for neighbor in graph[node]]  # Assuming all weights are equal to 1
    if max_steps <= 0:
        return float("inf"), None

    if target is None:
        target = source
    if source == target:
        return 0, path

    if source in visited:
        return float("inf"), None

    visited.add(source)

    if target not in graph:
        return float("inf"), None

    if len(graph[source]) == 0:
        return float("inf"), None

    shortest_path_cost = float("inf")
    best_path = None

    for neighbor, weight in graph[source]:
        new_steps = max_steps - 1
        new_cost, new_path = _shortest_path(graph, neighbor, target, new_steps, visited, edge_weights, path + [neighbor])
        if new_cost != float("inf"):
            if new_cost + weight < shortest_path_cost:
                shortest_path_cost = new_cost + weight
                best_path = new_path

    return shortest_path_cost, best_path

